"use client";

import { useTranslation } from "react-i18next";
import { TUser } from "@formbricks/types/user";

interface AccountActivityProps {
  user: TUser;
}

export const AccountActivity = ({ user }: AccountActivityProps) => {
  const { t } = useTranslation();

  const formatDate = (date: Date | null): string => {
    if (!date) return t("workspace.settings.profile.no_login_yet");
    return new Intl.DateTimeFormat(undefined, {
      year: "numeric",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    }).format(new Date(date));
  };

  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
      <div>
        <p className="text-sm font-medium text-slate-600">{t("workspace.settings.profile.account_created")}</p>
        <p className="mt-1 text-sm text-slate-900">{formatDate(user.createdAt)}</p>
      </div>
      <div>
        <p className="text-sm font-medium text-slate-600">{t("workspace.settings.profile.last_login")}</p>
        <p className="mt-1 text-sm text-slate-900">{formatDate(user.lastLoginAt)}</p>
      </div>
    </div>
  );
};

"use client";

import { useState } from "react";
import { useTranslation } from "react-i18next";
import { TUser } from "@formbricks/types/user";
import { Button } from "@/modules/ui/components/button";
import { downloadMyDataAction } from "../actions/download-my-data";

interface DownloadMyDataProps {
  user: TUser;
}

export const DownloadMyData = ({ user }: DownloadMyDataProps) => {
  const { t } = useTranslation();
  const [isDownloading, setIsDownloading] = useState(false);

  const handleDownload = async () => {
    setIsDownloading(true);
    try {
      const result = await downloadMyDataAction({ userId: user.id });
      if (result?.data) {
        const jsonString = JSON.stringify(result.data, null, 2);
        const blob = new Blob([jsonString], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = "formbricks-data.json";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
      }
    } catch {
      // Error is handled by the action client; nothing to do here.
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <Button
      variant="secondary"
      size="sm"
      onClick={handleDownload}
      loading={isDownloading}
      disabled={isDownloading}>
      {t("workspace.settings.profile.download_my_data")}
    </Button>
  );
};

import { type Locale } from "date-fns";
import { de, enUS, es, fr, hu, ja, nl, pt, ptBR, ro, ru, sv, tr, zhCN, zhTW } from "date-fns/locale";

const DEFAULT_LOCALE = "en-US";

const DEFAULT_DATE_DISPLAY_OPTIONS: Intl.DateTimeFormatOptions = {
  year: "numeric",
  month: "short",
  day: "numeric",
};

const DEFAULT_DATE_TIME_DISPLAY_OPTIONS: Intl.DateTimeFormatOptions = {
  year: "numeric",
  month: "long",
  day: "numeric",
  hour: "numeric",
  minute: "2-digit",
};

// Helper function to calculate difference in days between two dates
export const diffInDays = (date1: Date, date2: Date) => {
  const diffTime = Math.abs(date2.getTime() - date1.getTime());
  return Math.floor(diffTime / (1000 * 60 * 60 * 24));
};

export const formatDateForDisplay = (
  date: Date,
  locale: string = DEFAULT_LOCALE,
  options: Intl.DateTimeFormatOptions = DEFAULT_DATE_DISPLAY_OPTIONS
): string => {
  return new Intl.DateTimeFormat(locale, options).format(date);
};

export const formatDateTimeForDisplay = (
  date: Date,
  locale: string = DEFAULT_LOCALE,
  options: Intl.DateTimeFormatOptions = DEFAULT_DATE_TIME_DISPLAY_OPTIONS
): string => {
  return new Intl.DateTimeFormat(locale, options).format(date);
};

export const formatDateWithOrdinal = (date: Date, locale: string = DEFAULT_LOCALE): string => {
  return formatDateForDisplay(date, locale, {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  });
};

export const isValidDateString = (value: string) => {
  const regex = /^(?:\d{4}-\d{1,2}-\d{1,2}|\d{1,2}-\d{1,2}-\d{4})$/;

  if (!regex.test(value)) {
    return false;
  }

  const normalizedValue = /^\d{1,2}-\d{1,2}-\d{4}$/.test(value)
    ? value.replace(/(\d{1,2})-(\d{1,2})-(\d{4})/, "$3-$2-$1")
    : value;

  const date = new Date(normalizedValue);
  return !Number.isNaN(date.getTime());
};

export const getFormattedDateTimeString = (date: Date, timeZone: string = "UTC"): string => {
  const options: Intl.DateTimeFormatOptions = {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
    // Append the zone (e.g. "UTC", "GMT+8") so every exported/integrated Timestamp is
    // self-describing: rows written under different org settings stay distinguishable,
    // and downstream ETL never has to guess the zone.
    timeZoneName: "short",
    timeZone,
  };

  // An invalid IANA zone makes Intl.DateTimeFormat throw a RangeError. Degrade to UTC
  // rather than failing the entire export or integration delivery.
  try {
    return new Intl.DateTimeFormat("en-CA", options).format(date).replace(",", "");
  } catch {
    return new Intl.DateTimeFormat("en-CA", { ...options, timeZone: "UTC" }).format(date).replace(",", "");
  }
};

/**
 * Maps an app locale code to the date-fns locale the calendar needs for month names, weekday headers
 * and the first day of the week.
 *
 * `Intl` (which the formatters above use) takes the BCP 47 tag directly, but `react-day-picker` wants a
 * date-fns `Locale` object, so the app's locale codes have to be mapped explicitly. The keys mirror
 * `apps/web/locales/*.json`; anything else — including a survey language code that never became an app
 * locale — falls back to en-US rather than throwing.
 */
export const getDateFnsLocale = (localeCode?: string): Locale => {
  if (!localeCode) return enUS;

  const normalized = localeCode.toLowerCase();

  // Script-and-region-specific tags first: these do not survive being cut down to a base language
  // (pt-BR and pt-PT differ, and zh-Hans/zh-Hant are different scripts, not different regions).
  if (normalized.startsWith("pt-br")) return ptBR;
  if (normalized.startsWith("pt-pt")) return pt;
  if (normalized.startsWith("zh-hans") || normalized === "zh-cn") return zhCN;
  if (normalized.startsWith("zh-hant") || normalized === "zh-tw" || normalized === "zh-hk") return zhTW;

  const localeMap: Record<string, Locale> = {
    de,
    en: enUS,
    es,
    fr,
    hu,
    ja,
    nl,
    pt: ptBR, // Bare "pt" is ambiguous; Brazilian is the larger audience and matches the survey packages.
    ro,
    ru,
    sv,
    tr,
    zh: zhCN,
  };

  return localeMap[normalized.split("-")[0]] ?? enUS;
};

/**
 * Serialises a local calendar day as `yyyy-MM-dd`.
 *
 * Machine-facing on purpose — this is the value chart and dashboard time filters hand to Cube — so it
 * stays non-localized. Deliberately not `toISOString().slice(0, 10)`: that converts to UTC first, so
 * a user east of UTC would emit tomorrow's date and one west of it yesterday's.
 */
export const formatLocalDay = (date: Date): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
};

/**
 * Parses a `yyyy-MM-dd` day back to local midnight — the inverse of `formatLocalDay`.
 *
 * `new Date("2026-08-05")` parses as UTC midnight, which displays (and re-emits) a day earlier for
 * anyone west of UTC, so the value is rebuilt from its parts to keep the round trip symmetric.
 */
export const parseLocalDay = (value: string): Date => {
  const [year, month, day] = value.split("-").map(Number);

  return new Date(year, month - 1, day);
};

/**
 * Parses a stored date value — a bare `yyyy-MM-dd` or a full ISO timestamp — to the local midnight of
 * the calendar day it names, or `null` when it names none.
 *
 * The time part is dropped before parsing rather than handed to `Date`: a stored
 * `2026-08-05T00:00:00.000Z` is the 5th as written, and reading it as an instant would select the 4th
 * for any viewer west of UTC. Round-tripping through `formatLocalDay` accepts exactly the values an
 * `<input type="date">` did, so a value that predates the picker still renders, a rolled-over one
 * (`2026-13-45`) is refused rather than silently shown as a different day, and an unparseable one
 * yields `null` instead of the Invalid Date that would break the calendar.
 *
 * Only the day is validated, so a well-formed day followed by a malformed time still resolves to that
 * day. That is deliberate: the day is the part a date picker shows, these values can arrive from the
 * Management API rather than only from this UI, and the `<input type="date">` this replaced split on
 * `T` the same way — blanking a readable day over a broken time suffix would lose information.
 */
export const parseStoredDay = (value: string | null | undefined): Date | null => {
  if (!value) return null;

  const day = value.split("T")[0];
  const parsed = parseLocalDay(day);

  return formatLocalDay(parsed) === day ? parsed : null;
};

import type { TSurveyDateElement, TSurveyElement } from "@formbricks/types/surveys/elements";
import { formatDateWithOrdinal } from "./datetime";

export type TSurveyDateFormatMap = Partial<Record<string, TSurveyDateElement["format"]>>;

const ISO_STORED_DATE_PATTERN = /^(\d{4})-(\d{1,2})-(\d{1,2})$/;

const buildDate = (year: number, month: number, day: number): Date | null => {
  if ([year, month, day].some((value) => Number.isNaN(value))) {
    return null;
  }

  const parsedDate = new Date(year, month - 1, day);

  if (
    parsedDate.getFullYear() !== year ||
    parsedDate.getMonth() !== month - 1 ||
    parsedDate.getDate() !== day
  ) {
    return null;
  }

  return parsedDate;
};

const parseLegacyStoredDateValue = (value: string, format: TSurveyDateElement["format"]): Date | null => {
  const parts = value.split("-");

  if (parts.length !== 3 || parts.some((part) => !/^\d{1,4}$/.test(part))) {
    return null;
  }

  const [first, second, third] = parts.map(Number);

  switch (format) {
    case "M-d-y":
      return buildDate(third, first, second);
    case "d-M-y":
      return buildDate(third, second, first);
    case "y-M-d":
      return buildDate(first, second, third);
  }
};

export const parseStoredDateValue = (value: string, format?: TSurveyDateElement["format"]): Date | null => {
  const isoMatch = ISO_STORED_DATE_PATTERN.exec(value);

  if (isoMatch) {
    return buildDate(Number(isoMatch[1]), Number(isoMatch[2]), Number(isoMatch[3]));
  }

  if (format) {
    return parseLegacyStoredDateValue(value, format);
  }

  if (/^\d{1,2}-\d{1,2}-\d{4}$/.test(value)) {
    return parseLegacyStoredDateValue(value, "d-M-y");
  }

  return null;
};

export const formatStoredDateForDisplay = (
  value: string,
  format: TSurveyDateElement["format"] | undefined,
  locale: string = "en-US"
): string | null => {
  const parsedDate = parseStoredDateValue(value, format);

  if (!parsedDate) {
    return null;
  }

  return formatDateWithOrdinal(parsedDate, locale);
};

export const getSurveyDateFormatMap = (elements: TSurveyElement[]): TSurveyDateFormatMap => {
  return elements.reduce<TSurveyDateFormatMap>((dateFormats, element) => {
    if (element.type === "date") {
      dateFormats[element.id] = element.format;
    }

    return dateFormats;
  }, {});
};

"use server";

import { prisma } from "@formbricks/database";
import { z } from "zod";
import { ZId } from "@formbricks/types/common";
import { validateInputs } from "@/lib/utils/validate";
import { authenticatedActionClient } from "@/lib/utils/action-client";

export const ZDownloadMyDataInput = z.object({
  userId: ZId,
});

export type TDownloadMyDataInput = z.infer<typeof ZDownloadMyDataInput>;

export const downloadMyDataAction = authenticatedActionClient
  .inputSchema(ZDownloadMyDataInput)
  .action(async ({ ctx, parsedInput }) => {
    validateInputs([parsedInput.userId, ZId]);

    // Fetch user's memberships with organization names and roles
    const memberships = await prisma.membership.findMany({
      where: {
        userId: parsedInput.userId,
        accepted: true,
      },
      select: {
        organization: {
          select: {
            id: true,
            name: true,
          },
        },
        role: true,
      },
      orderBy: {
        organization: {
          name: "asc",
        },
      },
    });

    return {
      name: ctx.user.name,
      email: ctx.user.email,
      locale: ctx.user.locale,
      notificationSettings: ctx.user.notificationSettings,
      organizations: memberships.map((m) => ({
        organizationId: m.organization.id,
        organizationName: m.organization.name,
        role: m.role,
      })),
    };
  });

/**
 * /api/v3/action-classes - list a workspace's action classes (read-only).
 * Session cookie or x-api-key; scope by workspaceId only. Lets API/MCP clients discover the
 * action-class ids referenced by app-survey triggers (`distribution.triggers[].actionClassId`).
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZV3WorkspaceListQuery } from "@/app/api/v3/lib/schemas";
import { listV3ActionClasses } from "./lib/operations";

export const GET = withV3ApiWrapper({
  auth: "both",
  schemas: {
    query: ZV3WorkspaceListQuery,
  },
  handler: async ({ authentication, parsedInput, requestId, instance }) => {
    return await listV3ActionClasses({
      workspaceId: parsedInput.query.workspaceId,
      limit: parsedInput.query.limit,
      cursor: parsedInput.query.cursor,
      authentication,
      requestId,
      instance,
    });
  },
});

/**
 * POST /api/v3/responses/batch-delete — delete up to 100 responses in one transaction.
 *
 * A POST custom method rather than a `DELETE` on the collection: a collection-level delete that loses
 * its filters — a client bug, a proxy stripping the query string, a copied curl command — degrades into
 * erasing every response in scope, and a distinct path cannot be reached by accident. AIP-165 blesses
 * `batchDelete` for exactly this reason.
 *
 * A thin adapter on purpose: the orchestration lives in the operation and the service, which the MCP
 * server also calls directly with no wrapper around them.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { batchDeleteV3Responses } from "../lib/operations";
import { ZV3BatchDeleteResponsesBody, ZV3BatchDeleteResponsesQuery } from "../lib/schemas";

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "deleted",
  targetType: "response",
  schemas: { body: ZV3BatchDeleteResponsesBody, query: ZV3BatchDeleteResponsesQuery },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    batchDeleteV3Responses({
      authentication,
      workspaceId: parsedInput.query.workspaceId,
      ids: parsedInput.body.ids,
      auditLog,
      requestId,
      instance,
    }),
});

"use client";

import { useMutation } from "@tanstack/react-query";
import { UserCheckIcon } from "lucide-react";
import { useRouter } from "next/navigation";
import toast from "react-hot-toast";
import { useTranslation } from "react-i18next";
import { Button } from "@/modules/ui/components/button";
import { TooltipRenderer } from "@/modules/ui/components/tooltip";
import { reactivateMember } from "../../lib/reactivate-member-client";
import { getReactivateMemberErrorMessage } from "../../lib/reactivate-member-error";

interface ReactivateMemberButtonProps {
  organizationId: string;
  userId: string;
  name: string;
}

/**
 * "Reactivate" on an inactive member (ENG-3610): owners and managers bring back someone the members
 * policy, or anyone, deactivated, which restarts their retention clock. The API refuses someone who
 * also belongs to another organisation, and the toast says so. Runs under the member list's query
 * client (`MembersInfo`).
 */
export const ReactivateMemberButton = ({
  organizationId,
  userId,
  name,
}: Readonly<ReactivateMemberButtonProps>) => {
  const { t } = useTranslation();
  const router = useRouter();
  const reactivate = useMutation({ mutationFn: () => reactivateMember({ userId, organizationId }) });

  const onClick = () =>
    reactivate.mutate(undefined, {
      onSuccess: () => {
        toast.success(t("workspace.settings.data_retention.member_reactivated", { name }));
        // The member list is rendered on the server (an older module, not on the query cache), so the
        // page is re-rendered to show the new status. Moving the list onto a query is a follow-up.
        router.refresh();
      },
      onError: (error) => toast.error(getReactivateMemberErrorMessage(error, t)),
    });

  // An icon with a tooltip, like the row's other actions, so it doesn't widen the actions column.
  return (
    <TooltipRenderer tooltipContent={t("workspace.settings.data_retention.reactivate")}>
      <Button
        type="button"
        variant="secondary"
        size="icon"
        loading={reactivate.isPending}
        aria-label={t("workspace.settings.data_retention.reactivate_member_label", { name })}
        onClick={onClick}>
        <UserCheckIcon />
      </Button>
    </TooltipRenderer>
  );
};

import { parseV3ApiError } from "@/modules/api/lib/v3-client";

/** Reactivate a deactivated member of the organisation; their data retention clock restarts with it. */
export async function reactivateMember({
  userId,
  organizationId,
}: {
  userId: string;
  organizationId: string;
}): Promise<void> {
  const response = await fetch(
    `/api/internal/members/${encodeURIComponent(userId)}/reactivate?${new URLSearchParams({ organizationId })}`,
    { method: "POST", cache: "no-store", signal: AbortSignal.timeout(15_000) }
  );
  if (!response.ok) throw await parseV3ApiError(response);
}

export type TV3InvalidParam = {
  name: string;
  reason: string;
  /** What kind of problem, from v3's `InvalidParam.code`, when the operation sets one. */
  code?: string;
  /** The thing the problem is about, e.g. the import limit a file is past. */
  identifier?: string;
};

type TV3ProblemBody = {
  status?: number;
  detail?: string;
  code?: string;
  requestId?: string;
  invalid_params?: TV3InvalidParam[];
  details?: unknown;
};

export class V3ApiError extends Error {
  status: number;
  code?: string;
  requestId?: string;
  invalid_params?: TV3InvalidParam[];
  /** The problem's `details`, unparsed: their shape depends on `code`, so the caller reads them. */
  details?: unknown;
  /** Seconds to wait before asking again, from a 429's `Retry-After`. */
  retryAfter?: number;

  constructor({
    status,
    detail,
    code,
    requestId,
    invalid_params,
    details,
    retryAfter,
  }: {
    status: number;
    detail: string;
    code?: string;
    requestId?: string;
    invalid_params?: TV3InvalidParam[];
    details?: unknown;
    retryAfter?: number;
  }) {
    super(detail);
    this.name = "V3ApiError";
    this.status = status;
    this.code = code;
    this.requestId = requestId;
    this.invalid_params = invalid_params;
    this.details = details;
    this.retryAfter = retryAfter;
  }

  get detail(): string {
    return this.message;
  }
}

/** A 429 asking for a wait this short is a busy moment, worth waiting out; a longer one is a spent budget. */
const MAX_WAITED_RETRY_AFTER_SECONDS = 5;
/** How many such waits one read sits through before its error shows. */
const MAX_BUSY_RETRIES = 5;

/** A 429 that asks for a short wait, such as every in-flight chart query slot being taken. */
const isBriefBusy = (error: unknown): error is V3ApiError =>
  error instanceof V3ApiError &&
  error.status === 429 &&
  error.retryAfter !== undefined &&
  error.retryAfter <= MAX_WAITED_RETRY_AFTER_SECONDS;

/**
 * A TanStack Query `retry` policy for v3 reads: a 4xx is the server's answer, and asking again only
 * delays it — a dashboard the caller may not open spun for seconds through three retries before its
 * error showed, and every retry spent the caller's rate limit. Network failures and 5xx are retried up
 * to `maxRetries` times. The one 4xx retried is a 429 asking for a short wait (`Retry-After` of a few
 * seconds), so a large dashboard waits for a free chart query slot instead of showing errors.
 */
export const retryUnlessClientError =
  (maxRetries: number) =>
  (failureCount: number, error: unknown): boolean => {
    if (isBriefBusy(error)) return failureCount < MAX_BUSY_RETRIES;
    return (
      failureCount < maxRetries && !(error instanceof V3ApiError && error.status >= 400 && error.status < 500)
    );
  };

/**
 * The `retryDelay` that goes with `retryUnlessClientError`: a 429's own `Retry-After`, with a little
 * jitter so a dashboard's widgets do not all come back at once; otherwise TanStack's default backoff.
 */
export const v3RetryDelay = (failureCount: number, error: unknown): number =>
  isBriefBusy(error)
    ? (error.retryAfter as number) * 1000 + Math.floor(Math.random() * 500)
    : Math.min(1000 * 2 ** failureCount, 30_000);

export function getV3ApiErrorMessage(error: unknown, fallbackMessage: string): string {
  if (error instanceof V3ApiError) {
    return error.detail;
  }

  if (error instanceof Error && error.message) {
    return error.message;
  }

  return fallbackMessage;
}

export async function parseV3ApiError(response: Response): Promise<V3ApiError> {
  let problemBody: TV3ProblemBody | undefined;

  try {
    problemBody = (await response.json()) as TV3ProblemBody;
  } catch {
    problemBody = undefined;
  }

  return new V3ApiError({
    status: problemBody?.status ?? response.status,
    detail: problemBody?.detail ?? response.statusText ?? "An unexpected error occurred.",
    code: problemBody?.code,
    requestId: problemBody?.requestId ?? response.headers.get("X-Request-Id") ?? undefined,
    invalid_params: problemBody?.invalid_params,
    details: problemBody?.details,
    retryAfter: parseRetryAfterSeconds(response.headers.get("Retry-After")),
  });
}

/** `Retry-After` in its delay-seconds form; the HTTP-date form is not one v3 sends. */
const parseRetryAfterSeconds = (value: string | null): number | undefined => {
  if (value === null || !/^\d+$/.test(value.trim())) return undefined;
  return Number(value.trim());
};

